                  _record_delete!, _active_ids, _discretize_source, _replay!

_hist_domain() = create_domain([6.0, 8.0, 10.0], [2.0, 2.0, 2.0])

@testset "history: new domain" begin
    d = _hist_domain()
    @test isempty(d._history.steps)
    @test d._history.obj_counter == 0
    @test isempty(_active_ids(d._history))

    # internal field: hidden from tab completion, but still reachable
