@testset "history: create_brick! is recorded" begin
    d = create_domain([60.0, 80.0, 100.0], [20.0, 20.0, 20.0]; units="mm")
    id = create_brick!(d, 0, 20, 40, 40, 40, 20; units="mm", σ=5.8e7,
                       name="plate", color="#B87333")
    @test id == 1
    @test length(d._history.steps) == 1

    step = only(d._history.steps)
    @test step isa CreateObject
    @test step.obj_id == 1
