@testset "history: delete" begin
    d = _hist_domain()
    create_brick!(d, 0, 0, 0, 2, 2, 2)
    create_sphere!(d, 3, 4, 5, 2)

    _record_delete!(d, 1)
    @test d._history.steps[end] == DeleteObject(1)
    @test length(d._history.steps) == 3            # a delete is a step of its own
    @test _active_ids(d._history) == [2]
    @test d._history.obj_counter == 2              # deleting does not hand out an id

    @test_throws ArgumentError _record_delete!(d, 1)    # already deleted
    @test_throws ArgumentError _record_delete!(d, 99)   # never existed
    @test length(d._history.steps) == 3

    # a deleted id is never handed out again
    @test create_brick!(d, 0, 0, 0, 2, 2, 2) == 3
    @test _active_ids(d._history) == [2, 3]
end

