    @test step.object.radius ≈ 8.0
    @test step.object.normal == DirX()
    @test step.object.current == 1.0                       # default: 1 A, as before
    @test _discretize_source(d, step.object) == J           # the record reproduces J

    # current scales the vector
    d2 = wire_domain()
    J2 = get_source(d2, create_circular_loop_source!(d2, 8.0, 10.3, 15.2, 14.9, DirX(); current=1000.0))
